fn frame(t: i32) {
    let tab = [0, 49, 90, 117, 127, 117, 90, 49, 0, -49, -90, -117, -127, -117, -90, -49];
    let text = [82, 85, 83, 84, 76, 73, 84, 69];
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    let cw: i32 = 26;
    let total: i32 = w + 8 * cw;
    host::display::clear(0x000010);
    let scroll: i32 = t * 2 % total;
    let mut i: i32 = 0;
    while i < 8 {
        let x: i32 = w - scroll + i * cw;
        let y: i32 = h / 2 - 12 + tab[(t / 2 + i * 3) & 15] * 24 / 127;
        host::display::draw_char(x, y, text[i], 0x00ffaa, 3);
        i = i + 1;
    }
    host::display::present();
}
